-- 0131: verb templates (الصرف الصغير by root type). The ten sound templates were empty '{}' stubs;
-- they get their ف-ع-ل pattern, with one of our checked rows as the worked example (model_ref).
-- New: hollow (أجوف), doubled (مضعّف) and hamzated (مهموز الفاء/العين/اللام) templates, each a classic model
-- verb, plain "what changes" lines and a Qurʾān verse that shows the change; and PAR:template:amr, how the
-- command and prohibition are made for every form. All 57 verses checked against qr_ayah.text_uthmani.
-- Not yet: assimilated (مثال), defective (ناقص) and doubly weak (لفيف) roots.
UPDATE ar_ling_root_form_paradigm SET paradigm_json = '{"past": "فَعَلَ / فَعِلَ / فَعُلَ", "present": "يَفْعُلُ / يَفْعِلُ / يَفْعَلُ (by its bāb)", "masadir": ["learned per verb (سماعي): فَعْلٌ، فُعُولٌ، فِعَالَةٌ، فَعَلٌ…"], "active_participle": "فَاعِلٌ", "passive_participle": "مَفْعُولٌ", "passive_past": "فُعِلَ", "passive_present": "يُفْعَلُ", "imperative": "اُفْعُلْ (present u) / اِفْعِلْ (present i) / اِفْعَلْ (present a)", "prohibition": "لَا تَفْعُلْ / لَا تَفْعِلْ / لَا تَفْعَلْ", "noun_of_place_time": ["مَفْعَلٌ (present u or a)", "مَفْعِلٌ (present i)"], "noun_of_instrument": ["مِفْعَلٌ", "مِفْعَالٌ", "مِفْعَلَةٌ"], "by_bab": [{"bab_gt": "GT:form_family:bab_nasara", "past": "فَعَلَ", "present": "يَفْعُلُ", "imperative": "اُفْعُلْ", "model": "كَتَبَ يَكْتُبُ اُكْتُبْ", "model_ref": "PAR:كتب:I", "cite": {"surah": 7, "ayah": 156, "needle": "واكتب لنا"}}, {"bab_gt": "GT:form_family:bab_daraba", "past": "فَعَلَ", "present": "يَفْعِلُ", "imperative": "اِفْعِلْ", "model": "غَفَرَ يَغْفِرُ اِغْفِرْ", "model_ref": "PAR:غفر:I", "cite": {"surah": 2, "ayah": 286, "needle": "واغفر لنا"}}, {"bab_gt": "GT:form_family:bab_fataha", "past": "فَعَلَ", "present": "يَفْعَلُ", "imperative": "اِفْعَلْ", "model": "فَتَحَ يَفْتَحُ اِفْتَحْ", "note": "Only when the 2nd or 3rd letter is a throat letter (ء ه ع ح غ خ).", "cite": {"surah": 7, "ayah": 89, "needle": "ربنا افتح بيننا"}}, {"bab_gt": "GT:form_family:bab_samia", "past": "فَعِلَ", "present": "يَفْعَلُ", "imperative": "اِفْعَلْ", "model": "عَلِمَ يَعْلَمُ اِعْلَمْ", "model_ref": "PAR:علم:I", "cite": {"surah": 47, "ayah": 19, "needle": "فاعلم انه لا اله الا الله"}}, {"bab_gt": "GT:form_family:bab_hasiba", "past": "فَعِلَ", "present": "يَفْعِلُ", "imperative": "اِفْعِلْ", "model": "حَسِبَ يَحْسِبُ", "cite": {"surah": 104, "ayah": 3, "needle": "يحسب ان ماله اخلده"}}, {"bab_gt": "GT:form_family:bab_karuma", "past": "فَعُلَ", "present": "يَفْعُلُ", "imperative": "اُفْعُلْ (rare)", "model": "كَبُرَ يَكْبُرُ", "note": "Qualities (to be big, noble). Takes no object, so no passive.", "cite": {"surah": 61, "ayah": 3, "needle": "كبر مقتا عند الله"}}], "changes": ["The middle vowel of the present is learned per verb — that is its bāb.", "The maṣdar of the bare verb is learned per verb too; the derived forms (II–X) have fixed maṣdars."], "form_gt": "GT:form_family:form_i", "root_type_gt": "GT:root_type:sound"}', paradigm_name = 'فَعَلَ يَفْعُلُ — the bare verb (مجرّد)', status = 'live', source_slug = 'kmaps_synth', source_ref = 'ṣarf template; model verbs and verses checked against the muṣḥaf', root_type = 'sound' WHERE id = 'PAR:template:I:sound' AND paradigm_json = '{}';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = '{"past": "فَعَّلَ", "present": "يُفَعِّلُ", "masadir": ["تَفْعِيلًا"], "active_participle": "مُفَعِّلٌ", "passive_participle": "مُفَعَّلٌ", "passive_past": "فُعِّلَ", "passive_present": "يُفَعَّلُ", "imperative": "فَعِّلْ", "prohibition": "لَا تُفَعِّلْ", "noun_of_place_time": ["مُفَعَّلٌ"], "model_ref": "PAR:نزل:II", "cite": {"surah": 3, "ayah": 3, "needle": "نزل عليك الكتاب"}, "changes": ["Fixed maṣdar; noun of place/time has the object-noun shape (مُفَعَّلٌ)."], "form_gt": "GT:form_family:form_ii", "root_type_gt": "GT:root_type:sound"}', paradigm_name = 'فَعَّلَ يُفَعِّلُ — Form II', status = 'live', source_slug = 'kmaps_synth', source_ref = 'ṣarf template; model verbs and verses checked against the muṣḥaf', root_type = 'sound' WHERE id = 'PAR:template:II:sound' AND paradigm_json = '{}';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = '{"past": "فَاعَلَ", "present": "يُفَاعِلُ", "masadir": ["مُفَاعَلَةً", "فِعَالًا"], "active_participle": "مُفَاعِلٌ", "passive_participle": "مُفَاعَلٌ", "passive_past": "فُوعِلَ", "passive_present": "يُفَاعَلُ", "imperative": "فَاعِلْ", "prohibition": "لَا تُفَاعِلْ", "noun_of_place_time": ["مُفَاعَلٌ"], "model_ref": "PAR:عقب:III", "cite": {"surah": 16, "ayah": 126, "needle": "فعاقبوا بمثل ما عوقبتم به"}, "changes": ["Fixed maṣdar; noun of place/time has the object-noun shape (مُفَاعَلٌ)."], "form_gt": "GT:form_family:form_iii", "root_type_gt": "GT:root_type:sound"}', paradigm_name = 'فَاعَلَ يُفَاعِلُ — Form III', status = 'live', source_slug = 'kmaps_synth', source_ref = 'ṣarf template; model verbs and verses checked against the muṣḥaf', root_type = 'sound' WHERE id = 'PAR:template:III:sound' AND paradigm_json = '{}';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = '{"past": "أَفْعَلَ", "present": "يُفْعِلُ", "masadir": ["إِفْعَالًا"], "active_participle": "مُفْعِلٌ", "passive_participle": "مُفْعَلٌ", "passive_past": "أُفْعِلَ", "passive_present": "يُفْعَلُ", "imperative": "أَفْعِلْ", "prohibition": "لَا تُفْعِلْ", "noun_of_place_time": ["مُفْعَلٌ"], "model_ref": "PAR:نزل:IV", "cite": {"surah": 2, "ayah": 22, "needle": "وانزل من السماء ماء"}, "changes": ["Fixed maṣdar; noun of place/time has the object-noun shape (مُفْعَلٌ).", "The command keeps its own hamza, with fatḥa: أَنْزِلْ (not a helping hamza)."], "form_gt": "GT:form_family:form_iv", "root_type_gt": "GT:root_type:sound"}', paradigm_name = 'أَفْعَلَ يُفْعِلُ — Form IV', status = 'live', source_slug = 'kmaps_synth', source_ref = 'ṣarf template; model verbs and verses checked against the muṣḥaf', root_type = 'sound' WHERE id = 'PAR:template:IV:sound' AND paradigm_json = '{}';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = '{"past": "تَفَعَّلَ", "present": "يَتَفَعَّلُ", "masadir": ["تَفَعُّلًا"], "active_participle": "مُتَفَعِّلٌ", "passive_participle": "مُتَفَعَّلٌ", "passive_past": "تُفُعِّلَ", "passive_present": "يُتَفَعَّلُ", "imperative": "تَفَعَّلْ", "prohibition": "لَا تَتَفَعَّلْ", "noun_of_place_time": ["مُتَفَعَّلٌ"], "model_ref": "PAR:قبل:V", "cite": {"surah": 2, "ayah": 127, "needle": "ربنا تقبل منا"}, "changes": ["Fixed maṣdar; noun of place/time has the object-noun shape (مُتَفَعَّلٌ)."], "form_gt": "GT:form_family:form_v", "root_type_gt": "GT:root_type:sound"}', paradigm_name = 'تَفَعَّلَ يَتَفَعَّلُ — Form V', status = 'live', source_slug = 'kmaps_synth', source_ref = 'ṣarf template; model verbs and verses checked against the muṣḥaf', root_type = 'sound' WHERE id = 'PAR:template:V:sound' AND paradigm_json = '{}';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = '{"past": "تَفَاعَلَ", "present": "يَتَفَاعَلُ", "masadir": ["تَفَاعُلًا"], "active_participle": "مُتَفَاعِلٌ", "passive_participle": "مُتَفَاعَلٌ", "passive_past": "تُفُوعِلَ", "passive_present": "يُتَفَاعَلُ", "imperative": "تَفَاعَلْ", "prohibition": "لَا تَتَفَاعَلْ", "noun_of_place_time": ["مُتَفَاعَلٌ"], "model_ref": "PAR:قبل:VI", "cite": {"surah": 15, "ayah": 47, "needle": "علي سرر متقابلين"}, "changes": ["Fixed maṣdar; noun of place/time has the object-noun shape (مُتَفَاعَلٌ)."], "form_gt": "GT:form_family:form_vi", "root_type_gt": "GT:root_type:sound"}', paradigm_name = 'تَفَاعَلَ يَتَفَاعَلُ — Form VI', status = 'live', source_slug = 'kmaps_synth', source_ref = 'ṣarf template; model verbs and verses checked against the muṣḥaf', root_type = 'sound' WHERE id = 'PAR:template:VI:sound' AND paradigm_json = '{}';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = '{"past": "اِنْفَعَلَ", "present": "يَنْفَعِلُ", "masadir": ["اِنْفِعَالًا"], "active_participle": "مُنْفَعِلٌ", "imperative": "اِنْفَعِلْ", "prohibition": "لَا تَنْفَعِلْ", "cite": {"surah": 82, "ayah": 1, "needle": "اذا السماء انفطرت"}, "changes": ["Fixed maṣdar.", "Something happens to the subject; it takes no object, so it has no passive and no object noun."], "form_gt": "GT:form_family:form_vii", "root_type_gt": "GT:root_type:sound"}', paradigm_name = 'اِنْفَعَلَ يَنْفَعِلُ — Form VII', status = 'live', source_slug = 'kmaps_synth', source_ref = 'ṣarf template; model verbs and verses checked against the muṣḥaf', root_type = 'sound' WHERE id = 'PAR:template:VII:sound' AND paradigm_json = '{}';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = '{"past": "اِفْتَعَلَ", "present": "يَفْتَعِلُ", "masadir": ["اِفْتِعَالًا"], "active_participle": "مُفْتَعِلٌ", "passive_participle": "مُفْتَعَلٌ", "passive_past": "اُفْتُعِلَ", "passive_present": "يُفْتَعَلُ", "imperative": "اِفْتَعِلْ", "prohibition": "لَا تَفْتَعِلْ", "noun_of_place_time": ["مُفْتَعَلٌ"], "model_ref": "PAR:كتب:VIII", "cite": {"surah": 25, "ayah": 5, "needle": "اكتتبها"}, "changes": ["Fixed maṣdar; noun of place/time has the object-noun shape (مُفْتَعَلٌ).", "After ص ض ط ظ the ت becomes ط: اِصْطَبَرَ (19:65).", "After د ذ ز it becomes د: اُزْدُجِرَ (54:9).", "A first و or ي (and the ء of أخذ) merges into it: اِتَّقَى، اِتَّخَذَ."], "form_gt": "GT:form_family:form_viii", "root_type_gt": "GT:root_type:sound"}', paradigm_name = 'اِفْتَعَلَ يَفْتَعِلُ — Form VIII', status = 'live', source_slug = 'kmaps_synth', source_ref = 'ṣarf template; model verbs and verses checked against the muṣḥaf', root_type = 'sound' WHERE id = 'PAR:template:VIII:sound' AND paradigm_json = '{}';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = '{"past": "اِفْعَلَّ", "present": "يَفْعَلُّ", "masadir": ["اِفْعِلَالًا"], "active_participle": "مُفْعَلٌّ", "imperative": "اِفْعَلَّ / اِفْعَلِلْ", "prohibition": "لَا تَفْعَلَّ", "cite": {"surah": 3, "ayah": 106, "needle": "يوم تبيض وجوه وتسود وجوه"}, "changes": ["Fixed maṣdar.", "Only colours and body marks (to turn black, white). Takes no object, so no passive."], "form_gt": "GT:form_family:form_ix", "root_type_gt": "GT:root_type:sound"}', paradigm_name = 'اِفْعَلَّ يَفْعَلُّ — Form IX', status = 'live', source_slug = 'kmaps_synth', source_ref = 'ṣarf template; model verbs and verses checked against the muṣḥaf', root_type = 'sound' WHERE id = 'PAR:template:IX:sound' AND paradigm_json = '{}';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = '{"past": "اِسْتَفْعَلَ", "present": "يَسْتَفْعِلُ", "masadir": ["اِسْتِفْعَالًا"], "active_participle": "مُسْتَفْعِلٌ", "passive_participle": "مُسْتَفْعَلٌ", "passive_past": "اُسْتُفْعِلَ", "passive_present": "يُسْتَفْعَلُ", "imperative": "اِسْتَفْعِلْ", "prohibition": "لَا تَسْتَفْعِلْ", "noun_of_place_time": ["مُسْتَفْعَلٌ"], "model_ref": "PAR:غفر:X", "cite": {"surah": 71, "ayah": 10, "needle": "استغفروا ربكم"}, "changes": ["Fixed maṣdar; noun of place/time has the object-noun shape (مُسْتَفْعَلٌ)."], "form_gt": "GT:form_family:form_x", "root_type_gt": "GT:root_type:sound"}', paradigm_name = 'اِسْتَفْعَلَ يَسْتَفْعِلُ — Form X', status = 'live', source_slug = 'kmaps_synth', source_ref = 'ṣarf template; model verbs and verses checked against the muṣḥaf', root_type = 'sound' WHERE id = 'PAR:template:X:sound' AND paradigm_json = '{}';
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, note_md, source_slug, source_ref, bab_key, status, layer_code, name_en) VALUES ('PAR:template:I:hollow_w:nasara', 'قَالَ يَقُولُ — Form I', 'conjugation_template', 'I', 'hollow_w', '{"past": "قَالَ", "present": "يَقُولُ", "masadir": ["قَوْلًا", "مَقَالًا"], "active_participle": "قَائِلٌ", "passive_participle": "مَقُولٌ", "passive_past": "قِيلَ", "passive_present": "يُقَالُ", "imperative": "قُلْ", "prohibition": "لَا تَقُلْ", "noun_of_place_time": ["مَقَالٌ"], "model": true, "cite": {"surah": 112, "ayah": 1, "needle": "قل هو الله احد"}, "changes": ["The middle و turns to alif in the past: قَوَلَ → قَالَ.", "It shows as و in the present: يَقُولُ.", "It drops when the last letter has sukūn: قُلْ، لَمْ يَقُلْ، قُلْتُ.", "The doer noun puts hamza in its place: قَائِلٌ. Passive past: قِيلَ."], "model_ref": "PAR:توب:I", "bab_gt": "GT:form_family:bab_nasara", "form_gt": "GT:form_family:form_i", "root_type_gt": "GT:root_type:hollow_w"}', NULL, 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', 'bab_nasara', 'live', 'AL:150-FORM:SF:22-BAB:P', NULL);
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, note_md, source_slug, source_ref, bab_key, status, layer_code, name_en) VALUES ('PAR:template:I:hollow_y:daraba', 'سَارَ يَسِيرُ — Form I', 'conjugation_template', 'I', 'hollow_y', '{"past": "سَارَ", "present": "يَسِيرُ", "masadir": ["سَيْرًا", "مَسِيرًا"], "active_participle": "سَائِرٌ", "passive_participle": "مَسِيرٌ بِهِ", "passive_past": "سِيرَ بِهِ", "passive_present": "يُسَارُ بِهِ", "imperative": "سِرْ", "prohibition": "لَا تَسِرْ", "noun_of_place_time": ["مَسِيرٌ"], "model": true, "cite": {"surah": 6, "ayah": 11, "needle": "قل سيروا في الارض"}, "changes": ["The middle ي turns to alif in the past: سَيَرَ → سَارَ.", "It shows as ي in the present: يَسِيرُ.", "It drops when the last letter has sukūn: سِرْ، لَمْ يَسِرْ."], "model_ref": "PAR:صير:I", "bab_gt": "GT:form_family:bab_daraba", "form_gt": "GT:form_family:form_i", "root_type_gt": "GT:root_type:hollow_y"}', NULL, 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', 'bab_daraba', 'live', 'AL:150-FORM:SF:22-BAB:P', NULL);
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, note_md, source_slug, source_ref, bab_key, status, layer_code, name_en) VALUES ('PAR:template:I:hollow_w:samia', 'خَافَ يَخَافُ — Form I', 'conjugation_template', 'I', 'hollow_w', '{"past": "خَافَ", "present": "يَخَافُ", "masadir": ["خَوْفًا", "مَخَافَةً"], "active_participle": "خَائِفٌ", "passive_participle": "مَخُوفٌ", "passive_past": "خِيفَ", "passive_present": "يُخَافُ", "imperative": "خَفْ", "prohibition": "لَا تَخَفْ", "noun_of_place_time": ["مَخَافَةٌ"], "model": true, "cite": {"surah": 20, "ayah": 68, "needle": "قلنا لا تخف"}, "changes": ["Bāb samiʿa: the middle letter is alif in past and present: خَافَ يَخَافُ.", "It drops when the last letter has sukūn: خَفْ، لَا تَخَفْ."], "bab_gt": "GT:form_family:bab_samia", "form_gt": "GT:form_family:form_i", "root_type_gt": "GT:root_type:hollow_w"}', NULL, 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', 'bab_samia', 'live', 'AL:150-FORM:SF:22-BAB:P', NULL);
