INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, note_md, source_slug, source_ref, bab_key, status, layer_code, name_en) VALUES ('PAR:template:I:doubled:nasara', 'مَدَّ يَمُدُّ — Form I', 'conjugation_template', 'I', 'doubled', '{"past": "مَدَّ", "present": "يَمُدُّ", "masadir": ["مَدًّا"], "active_participle": "مَادٌّ", "passive_participle": "مَمْدُودٌ", "passive_past": "مُدَّ", "passive_present": "يُمَدُّ", "imperative": "مُدَّ / اُمْدُدْ", "prohibition": "لَا تَمُدَّ / لَا تَمْدُدْ", "noun_of_place_time": ["مَمَدٌّ"], "model": true, "cite": {"surah": 31, "ayah": 19, "needle": "واغضض من صوتك"}, "changes": ["The two like letters merge into one with shadda when both have vowels: مَدَدَ → مَدَّ.", "They come apart when the second has sukūn: مَدَدْتُ، يَمْدُدْنَ.", "So the command and prohibition have two right forms: merged (مُدَّ) and split (اُمْدُدْ).", "The Qurʾān uses the split forms: وَاغْضُضْ (31:19), اُشْدُدْ (20:31), وَلَا تَمْنُنْ (74:6)."], "model_ref": "PAR:شدد:I:nasara", "bab_gt": "GT:form_family:bab_nasara", "form_gt": "GT:form_family:form_i", "root_type_gt": "GT:root_type:doubled"}', NULL, 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', 'bab_nasara', 'live', 'AL:150-FORM:SF:22-BAB:P', NULL);
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, note_md, source_slug, source_ref, bab_key, status, layer_code, name_en) VALUES ('PAR:template:I:doubled:daraba', 'فَرَّ يَفِرُّ — Form I', 'conjugation_template', 'I', 'doubled', '{"past": "فَرَّ", "present": "يَفِرُّ", "masadir": ["فِرَارًا"], "active_participle": "فَارٌّ", "passive_past": "فُرَّ مِنْهُ", "passive_present": "يُفَرُّ مِنْهُ", "imperative": "فِرَّ / اِفْرِرْ", "prohibition": "لَا تَفِرَّ / لَا تَفْرِرْ", "noun_of_place_time": ["مَفَرٌّ"], "model": true, "cite": {"surah": 51, "ayah": 50, "needle": "ففروا الي الله"}, "changes": ["The two like letters merge into one with shadda when both have vowels: مَدَدَ → مَدَّ.", "They come apart when the second has sukūn: مَدَدْتُ، يَمْدُدْنَ.", "Noun of place: مَفَرٌّ — «أَيْنَ الْمَفَرُّ» (75:10)."], "model_ref": "PAR:عزز:I:daraba", "bab_gt": "GT:form_family:bab_daraba", "form_gt": "GT:form_family:form_i", "root_type_gt": "GT:root_type:doubled"}', NULL, 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', 'bab_daraba', 'live', 'AL:150-FORM:SF:22-BAB:P', NULL);
