INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, note_md, source_slug, source_ref, bab_key, status, layer_code, name_en) VALUES ('PAR:template:X:doubled', 'اِسْتَحَقَّ يَسْتَحِقُّ — Form X', 'conjugation_template', 'X', 'doubled', '{"past": "اِسْتَحَقَّ", "present": "يَسْتَحِقُّ", "masadir": ["اِسْتِحْقَاقًا"], "active_participle": "مُسْتَحِقٌّ", "passive_participle": "مُسْتَحَقٌّ", "passive_past": "اُسْتُحِقَّ", "passive_present": "يُسْتَحَقُّ", "imperative": "اِسْتَحِقَّ / اِسْتَحْقِقْ", "prohibition": "لَا تَسْتَحِقَّ", "model": true, "cite": {"surah": 5, "ayah": 107, "needle": "انهما استحقا اثما"}, "changes": ["The two like letters merge into one with shadda when both have vowels: مَدَدَ → مَدَّ.", "They come apart when the second has sukūn: مَدَدْتُ، يَمْدُدْنَ."], "form_gt": "GT:form_family:form_x", "root_type_gt": "GT:root_type:doubled"}', NULL, 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', NULL, 'live', 'AL:150-FORM:SF:22-BAB:P', NULL);
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, note_md, source_slug, source_ref, bab_key, status, layer_code, name_en) VALUES ('PAR:template:I:mahmuz_fa', 'أَخَذَ يَأْخُذُ — Form I', 'conjugation_template', 'I', 'mahmuz_fa', '{"past": "أَخَذَ", "present": "يَأْخُذُ", "masadir": ["أَخْذًا"], "active_participle": "آخِذٌ", "passive_participle": "مَأْخُوذٌ", "passive_past": "أُخِذَ", "passive_present": "يُؤْخَذُ", "imperative": "خُذْ", "prohibition": "لَا تَأْخُذْ", "noun_of_place_time": ["مَأْخَذٌ"], "model": true, "cite": {"surah": 7, "ayah": 199, "needle": "خذ العفو"}, "changes": ["Two hamzas side by side, the second with sukūn, become one long vowel: أَأْخِذٌ → آخِذٌ.", "Three verbs drop the hamza in the command: خُذْ، كُلْ (2:60)، مُرْ — but after وَ: وَأْمُرْ (20:132).", "Others keep it as a long vowel: أَذِنَ → اِيذَنْ; أَلِهَ → اِيلَهْ.", "The hamza''s seat follows the vowels: يَأْخُذُ، يُؤْخَذُ."], "model_ref": "PAR:اله:I", "bab_gt": "GT:form_family:bab_nasara", "form_gt": "GT:form_family:form_i", "root_type_gt": "GT:root_type:mahmuz_fa"}', NULL, 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', 'bab_nasara', 'live', 'AL:150-FORM:SF:22-BAB:P', NULL);
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, note_md, source_slug, source_ref, bab_key, status, layer_code, name_en) VALUES ('PAR:template:III:mahmuz_fa', 'آخَذَ يُؤَاخِذُ — Form III', 'conjugation_template', 'III', 'mahmuz_fa', '{"past": "آخَذَ", "present": "يُؤَاخِذُ", "masadir": ["مُؤَاخَذَةً"], "active_participle": "مُؤَاخِذٌ", "passive_participle": "مُؤَاخَذٌ", "passive_past": "أُوخِذَ", "passive_present": "يُؤَاخَذُ", "imperative": "آخِذْ", "prohibition": "لَا تُؤَاخِذْ", "model": true, "cite": {"surah": 2, "ayah": 286, "needle": "ربنا لا تؤاخذنا"}, "changes": ["The hamza and the alif of Form III join as آ: أَاخَذَ → آخَذَ.", "In the present the hamza sits on و: يُؤَاخِذُ."], "form_gt": "GT:form_family:form_iii", "root_type_gt": "GT:root_type:mahmuz_fa"}', NULL, 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', NULL, 'live', 'AL:150-FORM:SF:22-BAB:P', NULL);
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, note_md, source_slug, source_ref, bab_key, status, layer_code, name_en) VALUES ('PAR:template:IV:mahmuz_fa', 'آمَنَ يُؤْمِنُ — Form IV', 'conjugation_template', 'IV', 'mahmuz_fa', '{"past": "آمَنَ", "present": "يُؤْمِنُ", "masadir": ["إِيمَانًا"], "active_participle": "مُؤْمِنٌ", "passive_past": "أُومِنَ", "passive_present": "يُؤْمَنُ", "imperative": "آمِنْ", "prohibition": "لَا تُؤْمِنْ", "model": true, "cite": {"surah": 4, "ayah": 136, "needle": "امنوا بالله ورسوله"}, "changes": ["Form IV''s hamza meets the root''s hamza and they become a long vowel: أَأْمَنَ → آمَنَ، إِئْمَانٌ → إِيمَانٌ.", "In the present the root''s hamza sits on و: يُؤْمِنُ، مُؤْمِنٌ."], "form_gt": "GT:form_family:form_iv", "root_type_gt": "GT:root_type:mahmuz_fa"}', NULL, 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', NULL, 'live', 'AL:150-FORM:SF:22-BAB:P', NULL);
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, note_md, source_slug, source_ref, bab_key, status, layer_code, name_en) VALUES ('PAR:template:VIII:mahmuz_fa', 'اِتَّخَذَ يَتَّخِذُ — Form VIII', 'conjugation_template', 'VIII', 'mahmuz_fa', '{"past": "اِتَّخَذَ", "present": "يَتَّخِذُ", "masadir": ["اِتِّخَاذًا"], "active_participle": "مُتَّخِذٌ", "passive_participle": "مُتَّخَذٌ", "passive_past": "اُتُّخِذَ", "passive_present": "يُتَّخَذُ", "imperative": "اِتَّخِذْ", "prohibition": "لَا تَتَّخِذْ", "model": true, "cite": {"surah": 73, "ayah": 9, "needle": "فاتخذه وكيلا"}, "changes": ["In أخذ the hamza merges into the ت of Form VIII: اِئْتَخَذَ → اِتَّخَذَ.", "Other roots keep it: اِئْتَمَنَ — «الَّذِي اؤْتُمِنَ» (2:283)."], "form_gt": "GT:form_family:form_viii", "root_type_gt": "GT:root_type:mahmuz_fa"}', NULL, 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', NULL, 'live', 'AL:150-FORM:SF:22-BAB:P', NULL);
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, note_md, source_slug, source_ref, bab_key, status, layer_code, name_en) VALUES ('PAR:template:X:mahmuz_fa', 'اِسْتَأْذَنَ يَسْتَأْذِنُ — Form X', 'conjugation_template', 'X', 'mahmuz_fa', '{"past": "اِسْتَأْذَنَ", "present": "يَسْتَأْذِنُ", "masadir": ["اِسْتِئْذَانًا"], "active_participle": "مُسْتَأْذِنٌ", "passive_participle": "مُسْتَأْذَنٌ", "passive_past": "اُسْتُؤْذِنَ", "passive_present": "يُسْتَأْذَنُ", "imperative": "اِسْتَأْذِنْ", "prohibition": "لَا تَسْتَأْذِنْ", "model": true, "cite": {"surah": 24, "ayah": 62, "needle": "فاذا استاذنوك"}, "changes": ["The hamza stays; its seat follows the vowel before it: اِسْتَأْذَنَ، اِسْتِئْذَانٌ، اُسْتُؤْذِنَ."], "form_gt": "GT:form_family:form_x", "root_type_gt": "GT:root_type:mahmuz_fa"}', NULL, 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', NULL, 'live', 'AL:150-FORM:SF:22-BAB:P', NULL);
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, note_md, source_slug, source_ref, bab_key, status, layer_code, name_en) VALUES ('PAR:template:I:mahmuz_ain', 'سَأَلَ يَسْأَلُ — Form I', 'conjugation_template', 'I', 'mahmuz_ain', '{"past": "سَأَلَ", "present": "يَسْأَلُ", "masadir": ["سُؤَالًا", "مَسْأَلَةً"], "active_participle": "سَائِلٌ", "passive_participle": "مَسْئُولٌ", "passive_past": "سُئِلَ", "passive_present": "يُسْأَلُ", "imperative": "اِسْأَلْ / سَلْ", "prohibition": "لَا تَسْأَلْ", "model": true, "cite": {"surah": 2, "ayah": 211, "needle": "سل بني اسرائيل"}, "changes": ["Bāb fataḥa: the hamza is a throat letter.", "The hamza''s seat follows the vowels: سَأَلَ، سُئِلَ، مَسْئُولٌ.", "The command has two forms: اِسْأَلْ and the lighter سَلْ — «وَاسْأَلِ الْقَرْيَةَ» (12:82), «سَلْ بَنِي إِسْرَائِيلَ» (2:211)."], "bab_gt": "GT:form_family:bab_fataha", "form_gt": "GT:form_family:form_i", "root_type_gt": "GT:root_type:mahmuz_ain"}', NULL, 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', 'bab_fataha', 'live', 'AL:150-FORM:SF:22-BAB:P', NULL);
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, note_md, source_slug, source_ref, bab_key, status, layer_code, name_en) VALUES ('PAR:template:I:mahmuz_lam', 'قَرَأَ يَقْرَأُ — Form I', 'conjugation_template', 'I', 'mahmuz_lam', '{"past": "قَرَأَ", "present": "يَقْرَأُ", "masadir": ["قِرَاءَةً", "قُرْآنًا"], "active_participle": "قَارِئٌ", "passive_participle": "مَقْرُوءٌ", "passive_past": "قُرِئَ", "passive_present": "يُقْرَأُ", "imperative": "اِقْرَأْ", "prohibition": "لَا تَقْرَأْ", "noun_of_place_time": ["مَقْرَأٌ"], "model": true, "cite": {"surah": 96, "ayah": 1, "needle": "اقرا باسم ربك"}, "changes": ["Bāb fataḥa: the hamza is a throat letter.", "The last hamza stays; its seat follows the vowel before it: قَرَأَ، قُرِئَ، يَقْرَأُ."], "bab_gt": "GT:form_family:bab_fataha", "form_gt": "GT:form_family:form_i", "root_type_gt": "GT:root_type:mahmuz_lam"}', NULL, 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', 'bab_fataha', 'live', 'AL:150-FORM:SF:22-BAB:P', NULL);
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, note_md, source_slug, source_ref, bab_key, status, layer_code, name_en) VALUES ('PAR:template:amr', 'الأمر والنهي — making the command and the prohibition', 'imperative_rule', NULL, NULL, '{"steps": ["Start from the jussive present: لَمْ يَكْتُبْ → يَكْتُبْ.", "Drop the prefix: كْتُبْ.", "If the first letter now has sukūn, add a helping hamza: اُ when the middle vowel is u (اُكْتُبْ), اِ otherwise (اِغْفِرْ، اِعْلَمْ، اِسْتَغْفِرْ).", "Form IV keeps its own hamza with fatḥa: أَنْزِلْ، أَقِمْ.", "If the first letter has a vowel, no hamza is needed: نَزِّلْ، عَاقِبْ، تَقَبَّلْ، قُلْ، مُدَّ.", "The ending is the jussive''s: a weak middle letter drops (قُلْ، أَقِمْ); doubled letters may split (اُشْدُدْ).", "Prohibition = لَا + the jussive: لَا تَكْتُبْ، لَا تَخَفْ، لَا تُؤَاخِذْ."], "cite": {"surah": 20, "ayah": 31, "needle": "اشدد به ازري"}, "cite_more": [{"surah": 112, "ayah": 1, "needle": "قل هو الله احد"}, {"surah": 96, "ayah": 1, "needle": "اقرا باسم ربك"}, {"surah": 2, "ayah": 286, "needle": "ربنا لا تؤاخذنا"}], "exceptions": ["خُذْ، كُلْ، مُرْ drop their hamza (Form I, hamzated first letter).", "اِسْأَلْ has a lighter form سَلْ."]}', NULL, 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', NULL, 'live', 'AL:150-FORM:SF:22-BAB:P', NULL);
